  /**
   * @method
   * @name hitbtc#fetchOrderBooks
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data for multiple markets
   * @see https://api.hitbtc.com/#order-books
   * @param {string[]} [symbols] list of unified market symbols, all symbols
   * fetched if undefined, default is undefined
   * @param {int} [limit] max number of entries per orderbook to return, default
   * is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [order book structures]{@link
   * https://docs.ccxt.com/?id=order-book-structure} indexed by market symbol
   */
  std::shared_future<ccxt::any>
  fetchOrderBooks(ccxt::any symbols = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                   ccxt::any marketIdsInner = this->marketIds(symbols);
                   ::setValue(request, std::string("symbols"),
                              join(marketIdsInner, std::string(",")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("depth"), limit);
                 }
                 ccxt::any response = awaitValue(this->publicGetPublicOrderbook(
                     this->extend(request, params)));
                 ccxt::any result = ccxt::dict{};
                 ccxt::any marketIds = getObjectKeys(response);
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   ccxt::any marketId = ::getValue(marketIds, i);
                   ccxt::any orderbook =
                       this->safeDict(response, marketId, ccxt::dict{});
                   ccxt::any symbol = this->safeSymbol(marketId);
                   ccxt::any timestamp = this->parse8601(
                       this->safeString(orderbook, std::string("timestamp")));
                   ::setValue(result, symbol,
                              this->parseOrderBook(orderbook, symbol, timestamp,
                                                   std::string("bid"),
                                                   std::string("ask")));
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name hitbtc#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://api.hitbtc.com/#order-books
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("depth"), limit);
                        }
                        ccxt::any response =
                            awaitValue(this->publicGetPublicOrderbookSymbol(
                                this->extend(request, params)));
                        ccxt::any timestamp = this->parse8601(this->safeString(
                            response, std::string("timestamp")));
                        return this->parseOrderBook(response, symbol, timestamp,
                                                    std::string("bid"),
                                                    std::string("ask"));
                      })
        .share();
  }

  virtual ccxt::any parseTradingFee(ccxt::any fee,
                                    ccxt::any market = ccxt::any{}) {
    //
    //     {
    //         "symbol":"ARVUSDT", // returned from fetchTradingFees only
    //         "take_rate":"0.0009",
    //         "make_rate":"0.0009"
    //     }
    //
    ccxt::any taker = this->safeNumber(fee, std::string("take_rate"));
    ccxt::any maker = this->safeNumber(fee, std::string("make_rate"));
    ccxt::any marketId = this->safeString(fee, std::string("symbol"));
    ccxt::any symbol = this->safeSymbol(marketId, market);
    return ccxt::dict{
        {std::string("info"), fee},
        {std::string("symbol"), symbol},
        {std::string("taker"), taker},
        {std::string("maker"), maker},
        {std::string("percentage"), ccxt::any{}},
        {std::string("tierBased"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name hitbtc#fetchTradingFee
   * @description fetch the trading fees for a market
   * @see https://api.hitbtc.com/#get-trading-commission
   * @see https://api.hitbtc.com/#get-trading-commission-2
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<ccxt::any>
  fetchTradingFee(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = this->market(symbol);
                ccxt::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                ccxt::any response = ccxt::any{};
                if (isTrue(isEqual(::getValue(market, std::string("type")),
                                   std::string("spot")))) {
                  response = awaitValue(this->privateGetSpotFeeSymbol(
                      this->extend(request, params)));
                } else if (isTrue(
                               isEqual(::getValue(market, std::string("type")),
                                       std::string("swap")))) {
                  response = awaitValue(this->privateGetFuturesFeeSymbol(
                      this->extend(request, params)));
                } else {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(
                          " fetchTradingFee() not support this market type"))));
                }
                //
                //     {
                //         "take_rate":"0.0009",
                //         "make_rate":"0.0009"
                //     }
                //
                return this->parseTradingFee(response, market);
              })
            .share();
  }

  /**
   * @method
   * @name hitbtc#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://api.hitbtc.com/#get-all-trading-commissions
   * @see https://api.hitbtc.com/#get-all-trading-commissions-2
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any marketTypequeryVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchTradingFees"), ccxt::any{}, params);
                 ccxt::any marketType = ::getValue(marketTypequeryVariable, 0);
                 ccxt::any query = ::getValue(marketTypequeryVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateGetSpotFee(query));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   response = awaitValue(this->privateGetFuturesFee(query));
                 } else {
                   throw NotSupported(toString(
                       add(this->id, std::string(" fetchTradingFees() not "
                                                 "support this market type"))));
                 }
                 //
                 //     [
                 //         {
                 //             "symbol":"ARVUSDT",
                 //             "take_rate":"0.0009",
                 //             "make_rate":"0.0009"
                 //         }
                 //     ]
                 //
                 ccxt::any result = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(response));
                      postFixIncrement(i)) {
                   ccxt::any fee =
                       this->parseTradingFee(::getValue(response, i));
                   ccxt::any symbol = ::getValue(fee, std::string("symbol"));
                   if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                     ::setValue(result, symbol, fee);
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name hitbtc#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://api.hitbtc.com/#candles
   * @see https://api.hitbtc.com/#futures-index-price-candles
   * @see https://api.hitbtc.com/#futures-mark-price-candles
   * @see https://api.hitbtc.com/#futures-premium-index-candles
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding rate
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, 1000));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("period"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("from"),
                              this->iso8601(since));
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("until"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000));
                 }
                 ccxt::any price =
                     this->safeString(params, std::string("price"));
                 params = this->omit(params, std::string("price"));
                 ccxt::any response = ccxt::list{};
                 if (isTrue(isEqual(price, std::string("mark")))) {
                   response = awaitValue(
                       this->publicGetPublicFuturesCandlesMarkPriceSymbol(
                           this->extend(request, params)));
                 } else if (isTrue(isEqual(price, std::string("index")))) {
                   response = awaitValue(
                       this->publicGetPublicFuturesCandlesIndexPriceSymbol(
                           this->extend(request, params)));
                 } else if (isTrue(
                                isEqual(price, std::string("premiumIndex")))) {
                   response = awaitValue(
                       this->publicGetPublicFuturesCandlesPremiumIndexSymbol(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->publicGetPublicCandlesSymbol(
                       this->extend(request, params)));
                 }
                 //
                 // Spot and Swap
                 //
                 //     [
                 //         {
                 //             "timestamp": "2021-10-25T07:38:00.000Z",
                 //             "open": "4173.391",
                 //             "close": "4170.923",
                 //             "min": "4170.923",
                 //             "max": "4173.986",
                 //             "volume": "0.1879",
                 //             "volume_quote": "784.2517846"
                 //         }
                 //     ]
                 //
                 // Mark, Index and Premium Index
                 //
                 //     [
                 //         {
                 //             "timestamp": "2022-04-01T01:28:00.000Z",
                 //             "open": "45146.39",
                 //             "close": "45219.43",
                 //             "min": "45146.39",
                 //             "max": "45219.43"
                 //         },
                 //     ]
                 //
                 ccxt::any ohlcvs = this->toArray(response);
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    // Spot and Swap
    //
    //     {
    //         "timestamp":"2015-08-20T19:01:00.000Z",
    //         "open":"0.006",
    //         "close":"0.006",
    //         "min":"0.006",
    //         "max":"0.006",
    //         "volume":"0.003",
    //         "volume_quote":"0.000018"
    //     }
    //
    // Mark, Index and Premium Index
    //
    //     {
    //         "timestamp": "2022-04-01T01:28:00.000Z",
    //         "open": "45146.39",
    //         "close": "45219.43",
    //         "min": "45146.39",
    //         "max": "45219.43"
    //     },
    //
    return ccxt::list{
        this->parse8601(this->safeString(ohlcv, std::string("timestamp"))),
        this->safeNumber(ohlcv, std::string("open")),
        this->safeNumber(ohlcv, std::string("max")),
        this->safeNumber(ohlcv, std::string("min")),
        this->safeNumber(ohlcv, std::string("close")),
        this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name hitbtc#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see https://api.hitbtc.com/#spot-orders-history
   * @see https://api.hitbtc.com/#futures-orders-history
   * @see https://api.hitbtc.com/#margin-orders-history
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] 'cross' or 'isolated' only 'isolated'
   * is supported
   * @param {bool} [params.margin] true for fetching margin orders
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchClosedOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("from"),
                              this->iso8601(since));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marginMode = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchClosedOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchClosedOrders"), params);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 params =
                     this->omit(params, ccxt::list{std::string("marginMode"),
                                                   std::string("margin")});
                 ccxt::any response = ccxt::any{};
                 if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                   response = awaitValue(this->privateGetMarginHistoryOrder(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(marketType, std::string("spot")))) {
                     response = awaitValue(this->privateGetSpotHistoryOrder(
                         this->extend(request, params)));
                   } else if (isTrue(
                                  isEqual(marketType, std::string("swap")))) {
                     response = awaitValue(this->privateGetFuturesHistoryOrder(
                         this->extend(request, params)));
                   } else if (isTrue(
                                  isEqual(marketType, std::string("margin")))) {
                     response = awaitValue(this->privateGetMarginHistoryOrder(
                         this->extend(request, params)));
                   } else {
                     throw NotSupported(toString(add(
                         this->id, std::string(" fetchClosedOrders() not "
                                               "support this market type"))));
                   }
                 }
                 ccxt::any parsed =
                     this->parseOrders(response, market, since, limit);
                 return this->filterByArray(
                     parsed, std::string("status"),
                     ccxt::list{std::string("closed"), std::string("canceled")},
                     false);
               })
        .share();
  }

