  ccxt::any parseLeverage(ccxt::any leverage,
                          ccxt::any market = ccxt::any{}) override {
    ccxt::any marketId = this->safeString(leverage, std::string("symbol"));
    ccxt::any leverageValue =
        this->safeInteger(leverage, std::string("leverage"));
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("marginMode"),
         this->safeStringLower(leverage, std::string("type"))},
        {std::string("longLeverage"), leverageValue},
        {std::string("shortLeverage"), leverageValue},
    };
  }

  /**
   * @method
   * @name hitbtc#setLeverage
   * @description set the level of leverage for a market
   * @see https://api.hitbtc.com/#create-update-margin-account-2
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setLeverage(ccxt::any leverage, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(
                         ::getValue(params, std::string("margin_balance")),
                         ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(" setLeverage() requires a margin_balance "
                                   "parameter that will transfer margin to the "
                                   "specified trading pair"))));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any amount =
                     this->safeNumber(params, std::string("margin_balance"));
                 ccxt::any maxLeverage = this->safeInteger(
                     ::getValue(::getValue(market, std::string("limits")),
                                std::string("leverage")),
                     std::string("max"), 50);
                 if (isTrue(!isEqual(::getValue(market, std::string("type")),
                                     std::string("swap")))) {
                   throw BadSymbol(toString(add(
                       this->id,
                       std::string(
                           " setLeverage() supports swap contracts only"))));
                 }
                 if (isTrue(isTrue((isLessThan(leverage, 1))) ||
                            isTrue((isGreaterThan(leverage, maxLeverage))))) {
                   throw BadRequest(toString(
                       add(add(add(add(this->id,
                                       std::string(" setLeverage() leverage "
                                                   "should be between 1 and ")),
                                   toString(maxLeverage)),
                               std::string(" for ")),
                           symbol)));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("leverage"), toString(leverage)},
                     {std::string("margin_balance"),
                      this->amountToPrecision(symbol, amount)},
                 };
                 return awaitValue(this->privatePutFuturesAccountIsolatedSymbol(
                     this->extend(request, params)));
               })
        .share();
  }

