                        ccxt::any response =
                            awaitValue(this->publicGetPublicCurrency(params));
                        //
                        //     {
                        //       "WEALTH": {
                        //         "full_name": "ConnectWealth",
                        //         "payin_enabled": false,
                        //         "payout_enabled": false,
                        //         "transfer_enabled": true,
